from fractions import Fraction

def find_solutions(max_M, max_x1):
    solutions = []
    for M in range(1, max_M + 1):
        for x1 in range(2, max_x1 + 1):
            # For a fixed M and x1, we can search for x2, x3, ...
            def dfs(current_seq):
                i = len(current_seq) - 1
                if i == M:
                    s = sum(Fraction(current_seq[j-1], current_seq[j]) for j in range(1, M+1))
                    if s == Fraction(15, 16):
                        solutions.append(list(current_seq))
                    return

                S_i = sum(Fraction(current_seq[j-1], current_seq[j]) for j in range(1, i+1)) if i > 0 else Fraction(0)
                R_i = Fraction(15, 16) - S_i
                if R_i <= 0: return

                if i == 0: # this part won't be called with current_seq=[1, x1]
                    pass 
                else:
                    lower_bound = 1 + (current_seq[i]**3 - current_seq[i]**2) // current_seq[i-1]
                    if i + 1 == M:
                        x_next_frac = current_seq[i] / R_i
                        if x_next_frac.denominator == 1:
                            x_next = x_next_frac.numerator
                            if x_next >= lower_bound:
                                current_seq.append(x_next)
                                solutions.append(list(current_seq))
                                current_seq.pop()
                    else:
                        start_x = max(lower_bound, current_seq[i] // R_i + 1)
                        end_x = int(2 * current_seq[i] / R_i) + 1
                        for x_next in range(start_x, end_x):
                            current_seq.append(x_next)
                            dfs(current_seq)
                            current_seq.pop()

            dfs([1, x1])
    return solutions

print(find_solutions(5, 100))
